  "firstMeeting.maki": "先从诊断开始喵。别看我这样，我可是医生喵！",
  "firstMeeting.keris": "前辈，有想找的书吗？我给你带路。",
  "firstMeeting.delopi": "锵锵！这是你的钥匙，研究员。",
  "firstMeeting.nodonia": "疼的时候要告诉我哦，小家伙。我会替你挡下来的。",
  "firstMeeting.ella": "我会守住阵地。后方交给我。",
  "firstMeeting.mette": "只属于你的舞台，现在开幕。",
  "firstMeeting.deina": "我是黛依！这面墙还什么都没有呢？可以在这里画吗？",
  "firstMeeting.maddy": "我是玛蒂，研究员。这里有点热，能把冷气开大些吗？",
  "firstMeeting.terisa": "要是哪里破了请告诉我……我来为您缝好，研究员大人。",
  "firstMeeting.parua": "好远……好远啊！全都看得见。",
  "firstMeeting.shute": "都说了不是那个！听我指挥，我带飞你。",
  "firstMeeting.morphe": "……管理员？来得正好。稍等……我把画面调出来。",
  "firstMeeting.dian": "我会保护队长的！……啊，克罗！希罗！过来！",
