  "observation.shared-food.prompt": "如果要和同伴分享食物呢？",
  "observation.shared-food.share.label": "先留下同伴的那份",
  "observation.shared-food.share.tag": "体贴",
  "observation.shared-food.guard.label": "观察周围并定好顺序",
  "observation.shared-food.guard.tag": "秩序",
  "observation.torika-meal-appetite.prompt": "被问到平时吃多少、喜欢吃什么时，她会怎么反应？",
  "observation.torika-meal-appetite.torika-meal-eager.label": "开心地从最爱的食物说起",
  "observation.torika-meal-appetite.torika-meal-eager.tag": "好胃口",
  "observation.torika-meal-appetite.torika-meal-share.label": "先算好同伴们的份",
  "observation.torika-meal-appetite.torika-meal-share.tag": "关心同伴",
  "observation.torika-meal-appetite.torika-meal-shy.label": "少报吃了多少，只说出喜欢的叶子",
  "observation.torika-meal-appetite.torika-meal-shy.tag": "害羞",
  "observation.torika-weight-reaction.prompt": "提到体重时，托莉卡会怎么反应？",
