  "observation.torika-weight-reaction.torika-weight-honest.tag": "诚实",
  "observation.torika-weight-reaction.torika-weight-deflect.label": "遮住颈盾，赶紧转移话题",
  "observation.torika-weight-reaction.torika-weight-deflect.tag": "害羞",
  "observation.torika-frightened-shield.prompt": "明明害怕却必须站到别人前面时，她会怎么反应？",
  "observation.torika-frightened-shield.torika-shield-admit.label": "说自己害怕，退后一步但守住位置",
  "observation.torika-frightened-shield.torika-shield-admit.tag": "承认恐惧",
  "observation.torika-frightened-shield.torika-shield-protect.label": "撑住发抖的腿挡住去路",
