  "observation.rex-size-rivalry.prompt": "当体型大得多的对手挡住去路时，她会怎么反应？",
  "observation.rex-size-rivalry.rex-size-formal.label": "挺直身子，先正式提出比试",
  "observation.rex-size-rivalry.rex-size-formal.tag": "正式的较量",
  "observation.rex-size-rivalry.rex-size-wrestle.label": "一提到体型差距就立刻要求比力气",
  "observation.rex-size-rivalry.rex-size-wrestle.tag": "身体的较量",
  "observation.rex-strong-challenge.prompt": "遇到强大得压倒性的对手时，你会怎么做？",
