  "observation.rex-strong-challenge.rex-strong-fair.tag": "公平挑战",
  "observation.rex-strong-challenge.rex-strong-eager.label": "眼睛发亮，想马上分出谁更强",
  "observation.rex-strong-challenge.rex-strong-eager.tag": "被强大吸引",
  "observation.rex-small-etiquette.prompt": "如果小遗物不小心失礼了呢？",
  "observation.rex-small-etiquette.rex-small-guide.label": "先放低姿态，慢慢教正确的问候",
  "observation.rex-small-etiquette.rex-small-guide.tag": "温和的引导",
  "observation.rex-small-etiquette.rex-small-example.label": "先礼貌地问候，等对方跟着做",
  "observation.rex-small-etiquette.rex-small-example.tag": "以身作则",
  "observation.spino-night-alarm.prompt": "夜间巡逻时，如果水槽警报与其他区域的救援呼叫同时响起呢？",
  "observation.spino-night-alarm.spino-alarm-rescue.label": "简短报告救援地点，直接赶过去",
  "observation.spino-night-alarm.spino-alarm-rescue.tag": "任务优先",
  "observation.spino-night-alarm.spino-alarm-command.label": "把水槽检查交给最近的守卫，并清出救援路线",
  "observation.spino-night-alarm.spino-alarm-command.tag": "冷静指挥",
